float SignedDistanceFunc(vec3 Origin,vec3 Pos,float Size,int Type);
float SignedDistanceScene(vec3 Origin);

vec3 SpherePoint(vec2 Point,vec2 Offset);

//Settings
#define SPHERE 0
#define CUBE 1
#define WORLD 2
vec3[] ObjPos=vec3[](vec3(0,0,0),vec3(0,0,0));
float[] ObjSize=float[](1.5,15.);
int[] ObjType=int[](WORLD,SPHERE);

const float PI=3.1415926558979;
void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float FOV=PI/2.;
    float Sensitivity=PI*2.;
    vec2 Muv = (iMouse.xy/iResolution.xy-.5)*0.+vec2(iTime/100.,0);
    vec3 ViewPos = -SpherePoint(Muv*PI*vec2(2,1),vec2(0,0))*25.;

    int ILimit=15;
    float DistanceLimit=0.001;
    float Distance=0.;
    float NewDistance=0.;

    float DirectionX=FOV*(uv.x-.5)*(iResolution.x/iResolution.y);
    float DirectionY=FOV*(uv.y-.5);
    vec3 CameraDirection=SpherePoint(Muv*PI*vec2(2,1),vec2(DirectionX,DirectionY));

    int i;
    for(i=0;(i<ILimit);i++){
        NewDistance=SignedDistanceScene(Distance*CameraDirection+ViewPos);
        Distance+=NewDistance;
        if(NewDistance<DistanceLimit){
            break;
        }
    }

    float Falloff=40.;
    vec3 col = vec3(Distance/Falloff);

    // Output to screen
    fragColor = vec4(col,1.0);
}

float SignedDistanceFunc(vec3 Origin,vec3 Pos,float Size,int Type){
    switch (Type){
    case SPHERE:
        return length(Pos-Origin)-Size;
    break;

    case CUBE:
        return max(max(abs(Pos.x-Origin.x),abs(Pos.y-Origin.y)),abs(Pos.z-Origin.z))-Size;
    break;

    case WORLD:
        return sin(Pos.x+PI/2.-Origin.x*Size)+sin(Pos.y+PI/2.-Origin.y*Size)+sin(Pos.z+PI/2.-Origin.z*Size)+.2*Size;
    break;
    }
}
float SignedDistanceScene(vec3 Origin){
    float WorldDist = SignedDistanceFunc(Origin,ObjPos[0],ObjSize[0],ObjType[0]);
    float SphereDist = SignedDistanceFunc(Origin,ObjPos[1],ObjSize[1],ObjType[1]);
    return max(WorldDist,SphereDist);
}

vec3 SpherePoint(vec2 Point,vec2 Offset){
    vec3 Unrotated=vec3(sin(Offset.x),cos(Offset.y+Point.y)*cos(Offset.x),sin(Offset.y+Point.y)*cos(Offset.x));
    return vec3(Unrotated.x*cos(-Point.x)-Unrotated.y*sin(-Point.x),Unrotated.x*sin(-Point.x)+Unrotated.y*cos(-Point.x),Unrotated.z);
}
